-- Generated by tools/generate_native_encounter_library.py from the public Bastion Library export.
return {
  ["tofs-bailiff-of-borrowed-names"] = {overview = {"The tower's entrance register claims the admitted raid as new residents. Nhalvek creates counterfeits bearing players' names. Each owner must rely on someone else to kill their counterfeit.", "Assign cross-assist targets and two prisoner rescuers before the pull. Defeating Nhalvek commits the raid roster and starts its replay timer."}, roles = {{id = "everyone", label = "Everyone", tips = {"Attack another player's counterfeit; an owner cannot damage their own.", "Read the full names above the counterfeits and respond before they reach the register.", "Finalize the raid roster before this boss dies."}}, {id = "tank", label = "Tanks", tips = {"Handle bailiffs during the 40% prisoner intermission.", "Registered counterfeits can increase Nhalvek's melee; killing those counterfeits removes their enhancements."}}, {id = "damage", label = "Damage and control", tips = {"Counterfeits have 12,000 health and can be rooted or stunned.", "A registered counterfeit remains a valid priority target.", "Bailiffs at 40% can be rooted and mezzed."}}, {id = "rescuer", label = "Prisoner rescuers", tips = {"Assign one player to each chained prisoner at 40%.", "Complete the three-second release channel without taking damage.", "The boss cannot pass the health gate until both prisoners are free."}}}, phases = {{label = "Names on the register", trigger = "Every 40 seconds", description = "Up to three distinct living non-tanks receive counterfeits. The copies approach the register over 20 seconds; at most six counterfeits can be alive."}, {label = "Break the chains", trigger = "40% health", description = "Two prisoners and two 12,000-health bailiffs appear. Further name theft pauses until both three-second prisoner releases finish."}, {label = "The register is broken", trigger = "Nhalvek is defeated", description = "The library route opens. This first raid victory seals the roster and begins the 72-hour replay."}}, abilities = {{name = "Counterfeit Names", summary = "Cross-assist on another player's copy.", description = {"Each counterfeit belongs to its named owner. That owner cannot damage it, while other eligible participants can.", "When a counterfeit reaches the register, it can add one 5% outgoing-melee enhancement to Nhalvek. At most three enhancements coexist. Defeating that registered actor removes its own enhancement.", "Additional registered actors remain attackable even when the enhancement cap has been reached. New waves do not heal old counterfeits."}, tags = {"Cross-assist", "Adds", "Recoverable failure"}, roles = {"everyone"}}, {name = "Condemned Prisoners", summary = "Release both chains with uninterrupted three-second interactions.", description = {"The prisoners are protected from incidental area damage. Incoming damage interrupts a rescuer's channel.", "Nhalvek's normal melee continues, and his health cannot fall below 40% until the release objective is complete."}, tags = {"Required objective", "Shield gate", "Channel"}, roles = {"everyone"}}}, sections = {{title = "Expedition access and route", paragraphs = {"The Unwritten Hour admits 12 to 36 characters of level 55 or higher and is tuned for 24 to 36 level-60 raiders. Speak to Keeper Avel Rimeglass in Iceclad to arrange the expedition.", "The expedition lasts eight hours. A 72-hour replay begins when the first raid boss is defeated. That first victory seals the roster; arrange replacements beforehand. Disconnected members of the sealed roster may return before the expedition expires.", "The tower uses expedition mirrors and saved checkpoints. Ordinary tower keys, keyring entries and the summit shortcut do not unlock this version. Complete each floor objective before using the next mirror."}, bullets = {}}, {title = "Warnings and recovery", paragraphs = {"Read Event Messages and use the named encounter actors. Color and visual effects supplement the instructions; no required answer depends on recognizing a color alone. Keep the fight and its support inside the current encounter area.", "Evacuation returns eligible party members to the entrance of this same expedition. Gate and spells that transport you out of the tower remain available; reenter through the keeper while your expedition and membership remain valid. Binding, shadow steps, summons and transport within the tower cannot bypass its mirrors.", "A wipe restores the active boss and its attempt-only objectives. Previously completed encounters and route objectives remain completed. Cleared bosses cannot be repeated for another reward during the same expedition.", "An unsuccessful attempt does not consume another raid offering. A reset recreates temporary charges and actors for the next attempt. Return only to a checkpoint the expedition has already unlocked."}, bullets = {}}, {title = "Tower inhabitants", paragraphs = {"The full tower has 200 independent ambient positions across its floors and wings. Each area has between 12 and 44 inhabitants, including two native patrols, with more inhabitants in the larger rooms and corridors. Most see normal invisibility, many are genuinely undead, and nearby inhabitants can assist one another.", "Ordinary ambient kills do not complete the main named objectives, open mirrors, remove main named protections or award boss equipment or progression items.", "Ambient mobs can be rooted, mezzed, stunned or snared. Their saved 30-minute respawns wait near living players and during an engaged named fight on that floor. Native undead-targeted spells and invisibility-versus-undead detection use their actual body types.", "Ambient health ranges from 2,160 on the lowest floor to 6,240 at the summit. Native melee endpoints range from 36–96 to 66–186 before combat mitigation, about 20 percent above their previous tuning. The original spawn identities remain stable, so saved clears and respawn deadlines still apply after a reload."}, bullets = {}}}},
  ["tofs-supper-for-the-sightless"] = {overview = {"The Starvation Tender in the side dining area protects Gorveth from slows. Killing it before or during the fight removes that immunity for the rest of the expedition.", "Gorveth is a direct melee named with an announced stomp and a modest late-fight melee increase. There are no bells to click or hide phases to expose."}, roles = {{id = "everyone", label = "Everyone", tips = {"The leader chooses [begin] at the Echo Guide. Say [status] for the current combat objective.", "Pull when ready. Named abilities begin when the boss is engaged."}}, {id = "tank", label = "Tank", tips = {"Choose whether to pull the 2,800-HP Starvation Tender first.", "Step out of the marked stomp or help interrupt it."}}, {id = "damage", label = "Damage dealers", tips = {"Gorveth takes ordinary damage throughout the fight.", "Below 35% health, his melee rises ten percent."}}, {id = "support", label = "Healers and control", tips = {"The tender's death removes native slow immunity. Normal spell resistance and the boss's existing slow mitigation still apply.", "Heal through a missed 350 physical damage stomp; interrupts and movement can avoid it."}}}, phases = {{label = "Optional preclear", trigger = "Before or during Gorveth", description = "Kill the Starvation Tender to remove slow immunity. The named can be pulled with the tender alive."}, {label = "Gorveth", trigger = "Pull when ready", description = "Fight the named normally. A six-second stomp warning recurs every 30 seconds. Below 35%, Gorveth hits ten percent harder."}}, abilities = {{name = "Starvation Ward", summary = "Kill the tender to permit slows.", description = {"The living tender grants Gorveth native slow immunity. Its saved death removes that immunity immediately and keeps it removed after a wipe or reload. Other normal boss protections remain."}, tags = {"Support mob", "Immunity"}, roles = {"everyone"}}, {name = "Ravenous Stomp", summary = "Interrupt or leave the 12-pace circle.", description = {"Every 30 seconds, Gorveth pauses his melee and begins a six-second interruptible stomp. The circle is fixed at his casting position.", "A completed stomp deals 350 physical damage to players inside the circle through the native physical-damage path."}, tags = {"Physical damage", "Positioning", "Interruptible"}, roles = {"everyone"}}, {name = "Ravenous Hunger", summary = "Finish the fight through a modest melee increase.", description = {"Below 35% health, Gorveth gains ten percent melee damage. This does not halt damage or create another objective."}, tags = {"Melee"}, roles = {"everyone"}}}, sections = {{title = "Expedition access and route", paragraphs = {"The Seven Silences admits groups of three to six characters of level 55 or higher; six level-60 characters are recommended. Speak to Keeper Avel Rimeglass in Iceclad. Entry requires no raid trophy.", "The eight-hour expedition and replay begin at acceptance. The lower floors start below the difficulty of the Mistmoore group expedition, then increase toward comparable pressure on the upper floors.", "Ordinary tower keys, keyring entries and the summit shortcut do not unlock this version. Each floor victory unlocks the next expedition mirror and a cleared return checkpoint. The two wings of floor six form one encounter."}, bullets = {}}, {title = "Warnings and recovery", paragraphs = {"Read the named cast warnings and say [status] for the current objective. The leader chooses [begin] at the Echo Guide, then the party pulls when ready. Boss abilities begin on engagement; a completed disengage resets the attempt.", "Defeated prerequisite warders and optional support mobs are saved before their deaths are accepted. A wipe or reload retains these kills, previously won floors, paid admission and replay deadlines. Cleared bosses cannot be repeated for another reward during this expedition.", "The group floors require no carried tools, book choices, bells, rings or valves. Ordinary tower keys and movement shortcuts still cannot bypass the event mirrors. Every group boss retains one of its four equipment rewards and its independent splinter roll.", "Root, mez and stun can help with ordinary adds. Interrupting a named is optional; when a cast is missed, the party can move or heal as described. No random loot item is required to perform a mechanic."}, bullets = {}}, {title = "Tower inhabitants", paragraphs = {"The full tower has 200 independent ambient positions across its floors and wings. Each area has between 12 and 44 inhabitants, including two native patrols, with more inhabitants in the larger rooms and corridors. Most see normal invisibility, many are genuinely undead, and nearby inhabitants can assist one another.", "Ordinary ambient kills do not complete the main named objectives, open mirrors, remove main named protections or award boss equipment or progression items.", "Ambient mobs can be rooted, mezzed, stunned or snared. Their saved 30-minute respawns wait near living players and during an engaged named fight on that floor. Native undead-targeted spells and invisibility-versus-undead detection use their actual body types.", "Ambient health ranges from 2,160 on the lowest floor to 6,240 at the summit. Native melee endpoints range from 36–96 to 66–186 before combat mitigation, about 20 percent above their previous tuning. The original spawn identities remain stable, so saved clears and respawn deadlines still apply after a reload."}, bullets = {}}}},
  ["tofs-the-borrowed-furnace"] = {overview = {"Defeat the two route guards to open the opposite furnace wing. The Cinderlain's Brittle Conduit supplies both Furnace Breath and fifteen percent extra melee. Kill the conduit before or during the fight to disable those powers permanently, or control it temporarily.", "The named fight uses target selection, interrupts and ordinary damage. There is no pressure meter or valve operation."}, roles = {{id = "everyone", label = "Everyone", tips = {"The leader chooses [begin] at the Echo Guide. Say [status] for the current combat objective.", "Pull when ready. Named abilities begin when the boss is engaged."}}, {id = "tank", label = "Tank", tips = {"Kill the two 6,000-HP guards, cross the mirror and pull when ready.", "Choose whether to pull the 3,000-HP conduit before the named."}}, {id = "damage", label = "Damage dealers", tips = {"Destroy the conduit to remove Furnace Breath and the melee bonus for this expedition.", "Root, mez or stun it for temporary suppression. The powers return if control expires."}}, {id = "support", label = "Healers and control", tips = {"While a free conduit survives, Furnace Breath is an interruptible six-second cast every 36 seconds.", "A completed breath deals a 200 fire damage party pulse. Killing or controlling the conduit cancels a pending breath."}}}, phases = {{label = "Route guards", trigger = "Before the furnace wing opens", description = "Defeat both guards. Their kills are saved and unlock the opposite wing."}, {label = "Optional preclear", trigger = "Before or during the named", description = "Kill the Brittle Conduit to remove the named's breath and melee bonus permanently. Controlling it temporarily suppresses both powers."}, {label = "The Cinderlain", trigger = "Pull in the furnace wing", description = "Tank and defeat the named. Its ability clock waits for an actual pull, so travel across the floor does not run its spells."}}, abilities = {{name = "Brittle Conduit", summary = "Remove the source of two boss powers.", description = {"The conduit has 3,000 HP. While alive and uncontrolled, it grants fifteen percent extra melee and enables Furnace Breath.", "Its saved death keeps both powers disabled after a wipe. Crowd control suppresses them only for the duration of that control."}, tags = {"Support mob", "Crowd control"}, roles = {"everyone"}}, {name = "Furnace Breath", summary = "Interrupt or suppress the supply.", description = {"Every 36 seconds while the conduit is free, the Cinderlain begins a six-second interruptible cast. A completed cast deals a 200 fire damage party pulse.", "Killing or controlling the conduit cancels the current breath; there is no valve channel or pressure threshold."}, tags = {"Interruptible", "Fire damage"}, roles = {"everyone"}}}, sections = {{title = "Expedition access and route", paragraphs = {"The Seven Silences admits groups of three to six characters of level 55 or higher; six level-60 characters are recommended. Speak to Keeper Avel Rimeglass in Iceclad. Entry requires no raid trophy.", "The eight-hour expedition and replay begin at acceptance. The lower floors start below the difficulty of the Mistmoore group expedition, then increase toward comparable pressure on the upper floors.", "Ordinary tower keys, keyring entries and the summit shortcut do not unlock this version. Each floor victory unlocks the next expedition mirror and a cleared return checkpoint. The two wings of floor six form one encounter."}, bullets = {}}, {title = "Warnings and recovery", paragraphs = {"Read the named cast warnings and say [status] for the current objective. The leader chooses [begin] at the Echo Guide, then the party pulls when ready. Boss abilities begin on engagement; a completed disengage resets the attempt.", "Defeated prerequisite warders and optional support mobs are saved before their deaths are accepted. A wipe or reload retains these kills, previously won floors, paid admission and replay deadlines. Cleared bosses cannot be repeated for another reward during this expedition.", "The group floors require no carried tools, book choices, bells, rings or valves. Ordinary tower keys and movement shortcuts still cannot bypass the event mirrors. Every group boss retains one of its four equipment rewards and its independent splinter roll.", "Root, mez and stun can help with ordinary adds. Interrupting a named is optional; when a cast is missed, the party can move or heal as described. No random loot item is required to perform a mechanic."}, bullets = {}}, {title = "Tower inhabitants", paragraphs = {"The full tower has 200 independent ambient positions across its floors and wings. Each area has between 12 and 44 inhabitants, including two native patrols, with more inhabitants in the larger rooms and corridors. Most see normal invisibility, many are genuinely undead, and nearby inhabitants can assist one another.", "Ordinary ambient kills do not complete the main named objectives, open mirrors, remove main named protections or award boss equipment or progression items.", "Ambient mobs can be rooted, mezzed, stunned or snared. Their saved 30-minute respawns wait near living players and during an engaged named fight on that floor. Native undead-targeted spells and invisibility-versus-undead detection use their actual body types.", "Ambient health ranges from 2,160 on the lowest floor to 6,240 at the summit. Native melee endpoints range from 36–96 to 66–186 before combat mitigation, about 20 percent above their previous tuning. The original spawn identities remain stable, so saved clears and respawn deadlines still apply after a reload."}, bullets = {}}}},
  ["tofs-the-last-ember"] = {overview = {"Two Frostbound Warders keep the tower's first keeper asleep. Defeat them to release Nhalra in the far first-floor chamber, then pull her when the party is ready. The Last Ember is the warmth restored by victory; there is no lantern to carry or witness ritual to perform.", "This is the gentlest named fight of the ascent: tank Nhalra, avoid or interrupt her occasional frost burst, and pick up her two shades."}, roles = {{id = "everyone", label = "Everyone", tips = {"The leader chooses [begin] at the Echo Guide. Say [status] for the current combat objective.", "Pull when ready. Named abilities begin when the boss is engaged."}}, {id = "tank", label = "Tank", tips = {"Pull the two warders and then Nhalra. The warders have 1,800 HP each.", "Pick up the frostbound shades at 60% health."}}, {id = "damage", label = "Damage dealers", tips = {"Kill or control the shades. Nhalra remains vulnerable throughout combat.", "Step out of the marked frost circle or interrupt its six-second cast."}}, {id = "support", label = "Healers and control", tips = {"A missed frost burst deals 160 cold damage before native mitigation.", "Completed warder kills remain saved after a wipe."}}}, phases = {{label = "Frostbound Warders", trigger = "Before Nhalra appears", description = "Kill both warders in the entrance-side and middle side chambers. Each kill is saved; Nhalra appears only after both are dead."}, {label = "Nhalra", trigger = "Both warders are defeated", description = "Pull the keeper in the far side chamber. She uses a frost burst every 28 seconds and summons two shades once at 60% health. Defeat her to open the library mirror."}}, abilities = {{name = "Dying-Light Frost", summary = "Interrupt or leave the marked circle.", description = {"Every 28 seconds, Nhalra begins a six-second interruptible cast and pauses her melee. A 12-pace circle is marked at her casting position.", "A completed cast deals 160 cold damage inside that circle. Moving outside it avoids the burst. There are no ambient cold stacks or handoffs."}, tags = {"Interruptible", "Positioning"}, roles = {"everyone"}}, {name = "Frostbound Shades", summary = "Handle two adds at 60% health.", description = {"Two 1,200-HP shades join the fight once at 60%. They can be killed or controlled, and they do not make Nhalra invulnerable."}, tags = {"Adds", "Crowd control"}, roles = {"everyone"}}}, sections = {{title = "Expedition access and route", paragraphs = {"The Seven Silences admits groups of three to six characters of level 55 or higher; six level-60 characters are recommended. Speak to Keeper Avel Rimeglass in Iceclad. Entry requires no raid trophy.", "The eight-hour expedition and replay begin at acceptance. The lower floors start below the difficulty of the Mistmoore group expedition, then increase toward comparable pressure on the upper floors.", "Ordinary tower keys, keyring entries and the summit shortcut do not unlock this version. Each floor victory unlocks the next expedition mirror and a cleared return checkpoint. The two wings of floor six form one encounter."}, bullets = {}}, {title = "Warnings and recovery", paragraphs = {"Read the named cast warnings and say [status] for the current objective. The leader chooses [begin] at the Echo Guide, then the party pulls when ready. Boss abilities begin on engagement; a completed disengage resets the attempt.", "Defeated prerequisite warders and optional support mobs are saved before their deaths are accepted. A wipe or reload retains these kills, previously won floors, paid admission and replay deadlines. Cleared bosses cannot be repeated for another reward during this expedition.", "The group floors require no carried tools, book choices, bells, rings or valves. Ordinary tower keys and movement shortcuts still cannot bypass the event mirrors. Every group boss retains one of its four equipment rewards and its independent splinter roll.", "Root, mez and stun can help with ordinary adds. Interrupting a named is optional; when a cast is missed, the party can move or heal as described. No random loot item is required to perform a mechanic."}, bullets = {}}, {title = "Tower inhabitants", paragraphs = {"The full tower has 200 independent ambient positions across its floors and wings. Each area has between 12 and 44 inhabitants, including two native patrols, with more inhabitants in the larger rooms and corridors. Most see normal invisibility, many are genuinely undead, and nearby inhabitants can assist one another.", "Ordinary ambient kills do not complete the main named objectives, open mirrors, remove main named protections or award boss equipment or progression items.", "Ambient mobs can be rooted, mezzed, stunned or snared. Their saved 30-minute respawns wait near living players and during an engaged named fight on that floor. Native undead-targeted spells and invisibility-versus-undead detection use their actual body types.", "Ambient health ranges from 2,160 on the lowest floor to 6,240 at the summit. Native melee endpoints range from 36–96 to 66–186 before combat mitigation, about 20 percent above their previous tuning. The original spawn identities remain stable, so saved clears and respawn deadlines still apply after a reload."}, bullets = {}}}},
  ["tofs-the-marriage-of-ash"] = {overview = {"Restore three names in the crypt before entering the chapel. Each restored witness provides one recoverable mistake during an attempt.", "Avaris sends three contract pages toward the altar. The raid controls the risk by deciding when to destroy them: early pages become manageable adds, while late pages expose the boss and strengthen the next pulse."}, roles = {{id = "everyone", label = "Everyone", tips = {"Agree on an early or late page plan before combat.", "Read the final-section markers and the announced pulse warning.", "The page is the attackable target; the pallbearer is not."}}, {id = "damage", label = "Page damage", tips = {"Each page has 3,000 health and a 24-second journey to the altar.", "Early destruction creates a 6,000-health ash add.", "Late destruction inside the final marked section grants an eight-second boss vulnerability but raises the procession pulse."}}, {id = "tank", label = "Tanks and control", tips = {"Root, mez or tank ash adds from early pages.", "At the six-add cap, an early page instead strengthens an existing add briefly."}}, {id = "healer", label = "Healers", tips = {"The procession pulse occurs 26 seconds after the pages spawn.", "Prepare for 650, 850 or 900 damage according to the worst unresolved outcome in that procession.", "A six-second warning gives the current pulse strength and warns that unresolved pages can still raise it."}}}, phases = {{label = "Restore the witnesses", trigger = "Crypt preparation", description = "Match three remains to their inscriptions using the in-zone clues. All three can be restored before combat."}, {label = "The contract approaches", trigger = "Every 35 seconds", description = "Three page actors travel fixed lanes toward the altar. Their arrival takes 24 seconds; the procession pulse follows at 26 seconds."}, {label = "The final procession", trigger = "30% health", description = "Processions accelerate to every 28 seconds. No more than six page actors are alive at once."}}, abilities = {{name = "Burn It Before It Binds", summary = "Destroy a page before the final marked lane section.", description = {"The early page creates one 6,000-health ash add and grants no offensive bonus. This is the cautious route.", "At six living ash adds, another early destruction instead gives one existing add 25% extra melee damage for ten seconds. That bonus does not stack."}, tags = {"Adds", "Cautious option"}, roles = {"everyone"}}, {name = "The Last Word", summary = "Destroy a page inside the final section before it reaches the altar.", description = {"Avaris takes 15% extra damage for eight seconds, and the procession pulse rises from 650 to 850 damage.", "More late pages refresh the vulnerability window; they do not multiply its strength or repeatedly increase that pulse."}, tags = {"Damage window", "Risk choice"}, roles = {"everyone"}}, {name = "An Intact Contract", summary = "Use rescued witnesses as recovery, not as the normal plan.", description = {"A page arriving intact exhausts one witness for the attempt. Witnesses return on a wipe.", "Without a witness, each intact page heals Avaris for 3% of maximum health, up to 9% in a procession, and sets that procession's pulse to 900 damage.", "The pages cannot be charmed, rooted, slowed or stunned. Their timing is controlled by damage and positioning."}, tags = {"Recoverable failure", "Shared charges"}, roles = {"everyone"}}, {name = "The Ritual Pulse", summary = "Prepare for a pulse six seconds after its warning; unresolved pages can still increase its strength.", description = {"Each procession produces one pulse 26 seconds after its spawn. The worst uncanceled outcome determines its damage: 650, 850 or 900.", "Several page failures do not create several simultaneous raidwide pulses."}, tags = {"Six-second warning", "Raid healing"}, roles = {"everyone"}}}, sections = {{title = "Expedition access and route", paragraphs = {"The Unwritten Hour admits 12 to 36 characters of level 55 or higher and is tuned for 24 to 36 level-60 raiders. Speak to Keeper Avel Rimeglass in Iceclad to arrange the expedition.", "The expedition lasts eight hours. A 72-hour replay begins when the first raid boss is defeated. That first victory seals the roster; arrange replacements beforehand. Disconnected members of the sealed roster may return before the expedition expires.", "The tower uses expedition mirrors and saved checkpoints. Ordinary tower keys, keyring entries and the summit shortcut do not unlock this version. Complete each floor objective before using the next mirror."}, bullets = {}}, {title = "Warnings and recovery", paragraphs = {"Read Event Messages and use the named encounter actors. Color and visual effects supplement the instructions; no required answer depends on recognizing a color alone. Keep the fight and its support inside the current encounter area.", "Evacuation returns eligible party members to the entrance of this same expedition. Gate and spells that transport you out of the tower remain available; reenter through the keeper while your expedition and membership remain valid. Binding, shadow steps, summons and transport within the tower cannot bypass its mirrors.", "A wipe restores the active boss and its attempt-only objectives. Previously completed encounters and route objectives remain completed. Cleared bosses cannot be repeated for another reward during the same expedition.", "An unsuccessful attempt does not consume another raid offering. A reset recreates temporary charges and actors for the next attempt. Return only to a checkpoint the expedition has already unlocked."}, bullets = {}}, {title = "Tower inhabitants", paragraphs = {"The full tower has 200 independent ambient positions across its floors and wings. Each area has between 12 and 44 inhabitants, including two native patrols, with more inhabitants in the larger rooms and corridors. Most see normal invisibility, many are genuinely undead, and nearby inhabitants can assist one another.", "Ordinary ambient kills do not complete the main named objectives, open mirrors, remove main named protections or award boss equipment or progression items.", "Ambient mobs can be rooted, mezzed, stunned or snared. Their saved 30-minute respawns wait near living players and during an engaged named fight on that floor. Native undead-targeted spells and invisibility-versus-undead detection use their actual body types.", "Ambient health ranges from 2,160 on the lowest floor to 6,240 at the summit. Native melee endpoints range from 36–96 to 66–186 before combat mitigation, about 20 percent above their previous tuning. The original spawn identities remain stable, so saved clears and respawn deadlines still apply after a reload."}, bullets = {}}}},
  ["tofs-the-missing-chapter"] = {overview = {"The Silencing Scribe in the side library sustains Archivist Ezzelin's forbidden chapter. Killing the scribe before or during the named fight removes that cold spell for the rest of the expedition.", "You can fight Ezzelin with the scribe alive, interrupting his cast or healing through it. The decision is made by pulling and killing enemies; there are no book selections or half-health pauses."}, roles = {{id = "everyone", label = "Everyone", tips = {"The leader chooses [begin] at the Echo Guide. Say [status] for the current combat objective.", "Pull when ready. Named abilities begin when the boss is engaged."}}, {id = "tank", label = "Tank", tips = {"Choose whether to pull the 2,200-HP scribe first.", "Pick up Ezzelin's loose pages at half health."}}, {id = "damage", label = "Damage dealers", tips = {"Kill the scribe to cancel a current cold cast and stop future casts.", "Two 1,800-HP loose pages appear at 50%; the boss remains vulnerable."}}, {id = "support", label = "Healers and control", tips = {"With the scribe alive, Forbidden Chapter is an interruptible six-second cast every 30 seconds.", "A missed interrupt deals a 225 cold damage party pulse. Killing the scribe is a class-independent way to suppress it."}}}, phases = {{label = "Optional preclear", trigger = "Before or during Ezzelin", description = "Defeat the Silencing Scribe in the side library to suppress Forbidden Chapter. Its death is saved."}, {label = "Ezzelin", trigger = "Pull the named when ready", description = "Tank the archivist, handle his two loose pages at half health, and interrupt his cold cast if the scribe still lives. No health gate stops damage."}}, abilities = {{name = "Forbidden Chapter", summary = "Kill the scribe or interrupt the cast.", description = {"While the Silencing Scribe lives, Ezzelin starts a six-second cast every 30 seconds. Completion deals a 225 cold damage party pulse.", "Killing the scribe cancels an active cast and permanently suppresses subsequent casts in this expedition. Failed persistence leaves the scribe at one HP and retains the ability until the kill can be saved."}, tags = {"Support mob", "Interruptible"}, roles = {"everyone"}}, {name = "Unbound Pages", summary = "Kill or control two loose pages.", description = {"Ezzelin summons two 1,800-HP pages once at 50% health. The spectral pages are ordinary adds. Killing the archivist ends the encounter even if they remain alive."}, tags = {"Adds", "Crowd control"}, roles = {"everyone"}}}, sections = {{title = "Expedition access and route", paragraphs = {"The Seven Silences admits groups of three to six characters of level 55 or higher; six level-60 characters are recommended. Speak to Keeper Avel Rimeglass in Iceclad. Entry requires no raid trophy.", "The eight-hour expedition and replay begin at acceptance. The lower floors start below the difficulty of the Mistmoore group expedition, then increase toward comparable pressure on the upper floors.", "Ordinary tower keys, keyring entries and the summit shortcut do not unlock this version. Each floor victory unlocks the next expedition mirror and a cleared return checkpoint. The two wings of floor six form one encounter."}, bullets = {}}, {title = "Warnings and recovery", paragraphs = {"Read the named cast warnings and say [status] for the current objective. The leader chooses [begin] at the Echo Guide, then the party pulls when ready. Boss abilities begin on engagement; a completed disengage resets the attempt.", "Defeated prerequisite warders and optional support mobs are saved before their deaths are accepted. A wipe or reload retains these kills, previously won floors, paid admission and replay deadlines. Cleared bosses cannot be repeated for another reward during this expedition.", "The group floors require no carried tools, book choices, bells, rings or valves. Ordinary tower keys and movement shortcuts still cannot bypass the event mirrors. Every group boss retains one of its four equipment rewards and its independent splinter roll.", "Root, mez and stun can help with ordinary adds. Interrupting a named is optional; when a cast is missed, the party can move or heal as described. No random loot item is required to perform a mechanic."}, bullets = {}}, {title = "Tower inhabitants", paragraphs = {"The full tower has 200 independent ambient positions across its floors and wings. Each area has between 12 and 44 inhabitants, including two native patrols, with more inhabitants in the larger rooms and corridors. Most see normal invisibility, many are genuinely undead, and nearby inhabitants can assist one another.", "Ordinary ambient kills do not complete the main named objectives, open mirrors, remove main named protections or award boss equipment or progression items.", "Ambient mobs can be rooted, mezzed, stunned or snared. Their saved 30-minute respawns wait near living players and during an engaged named fight on that floor. Native undead-targeted spells and invisibility-versus-undead detection use their actual body types.", "Ambient health ranges from 2,160 on the lowest floor to 6,240 at the summit. Native melee endpoints range from 36–96 to 66–186 before combat mitigation, about 20 percent above their previous tuning. The original spawn identities remain stable, so saved clears and respawn deadlines still apply after a reload."}, bullets = {}}}},
  ["tofs-the-uninvited-court"] = {overview = {"The library holds three testimonies that contradict the court's claims. Choose any two before entering the dining room. Their shared charges refresh for each attempt.", "Veylis recognizes one petitioner at a time. Defeating that petitioner opens a damage window and advances the public order. Attacking the wrong claim creates extra work."}, roles = {{id = "everyone", label = "Everyone", tips = {"Confirm the two testimonies before pulling.", "Read the full name of the recognized petitioner instead of guessing from position.", "Announce lectern use so the raid does not waste its shared charges."}}, {id = "tank", label = "Tanks", tips = {"Control petitioners and objections while maintaining Veylis.", "Wrong-order kills can produce up to two objections."}}, {id = "damage", label = "Damage dealers", tips = {"Focus the recognized 18,000-health petitioner.", "Use Veylis's 25-second exposures for boss damage.", "All three claims must end correctly before Veylis can die."}}, {id = "evidence", label = "Testimony callers", tips = {"Each selected testimony has two shared charges per attempt.", "Use the absent guest against the frost pulse, the servant against the advocate cast, and the posthumous signature to open a control window on objections."}}}, phases = {{label = "Choose the evidence", trigger = "Library preparation", description = "Discover the three labeled testimonies and select two. Choices persist and can be changed between attempts."}, {label = "One recognized claim", trigger = "Dining-room combat", description = "Only the announced petitioner takes full damage. The other two take 20% damage. Veylis takes 40% damage between exposures."}, {label = "A claim is disproved", trigger = "The recognized petitioner is defeated", description = "Veylis takes full damage for 25 seconds, then the next surviving claim is recognized."}, {label = "The court is unmasked", trigger = "All three claims end correctly", description = "Veylis remains exposed for the rest of the fight."}}, abilities = {{name = "Recognized Claim", summary = "Defeat the petitioner named by the court.", description = {"An unrecognized petitioner killed early returns with its prior claim state and creates a 14,000-health objection, up to two alive.", "A mistaken kill gives no loot and does not advance recognition. Veylis cannot fall below 10% until all three claims have ended correctly."}, tags = {"Target order", "Required objective"}, roles = {"everyone"}}, {name = "All Voices Are Mine", summary = "Use the servant testimony or prepare to heal a 700 magic-damage room pulse.", description = {"The advocate starts this cast every 35 seconds with a six-second warning. The selected servant testimony can interrupt the otherwise protected cast.", "A separate 550 cold-damage pulse can be suppressed with the absent guest testimony. Major pulses remain at least ten seconds apart."}, tags = {"Six-second warning", "Testimony", "Raid healing"}, roles = {"everyone"}}, {name = "The Signature Written After Death", summary = "Temporarily make the objection adds controllable.", description = {"Invoking this selected testimony makes the current objections susceptible to mez and root for 20 seconds.", "All three testimony choices share their charges across the raid. Each chosen testimony has two uses per attempt."}, tags = {"Crowd control", "Shared charges"}, roles = {"everyone"}}}, sections = {{title = "Expedition access and route", paragraphs = {"The Unwritten Hour admits 12 to 36 characters of level 55 or higher and is tuned for 24 to 36 level-60 raiders. Speak to Keeper Avel Rimeglass in Iceclad to arrange the expedition.", "The expedition lasts eight hours. A 72-hour replay begins when the first raid boss is defeated. That first victory seals the roster; arrange replacements beforehand. Disconnected members of the sealed roster may return before the expedition expires.", "The tower uses expedition mirrors and saved checkpoints. Ordinary tower keys, keyring entries and the summit shortcut do not unlock this version. Complete each floor objective before using the next mirror."}, bullets = {}}, {title = "Warnings and recovery", paragraphs = {"Read Event Messages and use the named encounter actors. Color and visual effects supplement the instructions; no required answer depends on recognizing a color alone. Keep the fight and its support inside the current encounter area.", "Evacuation returns eligible party members to the entrance of this same expedition. Gate and spells that transport you out of the tower remain available; reenter through the keeper while your expedition and membership remain valid. Binding, shadow steps, summons and transport within the tower cannot bypass its mirrors.", "A wipe restores the active boss and its attempt-only objectives. Previously completed encounters and route objectives remain completed. Cleared bosses cannot be repeated for another reward during the same expedition.", "An unsuccessful attempt does not consume another raid offering. A reset recreates temporary charges and actors for the next attempt. Return only to a checkpoint the expedition has already unlocked."}, bullets = {}}, {title = "The three testimonies", paragraphs = {}, bullets = {"The Guest Who Never Arrived suppresses one court frost pulse.", "The Servant Who Heard the Vow interrupts one protected advocate cast.", "The Signature Written After Death opens a 20-second mez and root window on current objections.", "Choose two. Each chosen testimony has two shared uses for that attempt."}}, {title = "Tower inhabitants", paragraphs = {"The full tower has 200 independent ambient positions across its floors and wings. Each area has between 12 and 44 inhabitants, including two native patrols, with more inhabitants in the larger rooms and corridors. Most see normal invisibility, many are genuinely undead, and nearby inhabitants can assist one another.", "Ordinary ambient kills do not complete the main named objectives, open mirrors, remove main named protections or award boss equipment or progression items.", "Ambient mobs can be rooted, mezzed, stunned or snared. Their saved 30-minute respawns wait near living players and during an engaged named fight on that floor. Native undead-targeted spells and invisibility-versus-undead detection use their actual body types.", "Ambient health ranges from 2,160 on the lowest floor to 6,240 at the summit. Native melee endpoints range from 36–96 to 66–186 before combat mitigation, about 20 percent above their previous tuning. The original spawn identities remain stable, so saved clears and respawn deadlines still apply after a reload."}, bullets = {}}}},
  ["tofs-until-death-refuses"] = {overview = {"Two Ceremony Warders keep the wedding suspended. Kill them in the chapel to release Celebrant Orsella, then pull her when ready.", "The marriage still resists its end, but its answer is now a named fight: handle wedding ushers and interrupt the vow when possible. There are no rings, synchronized deliveries or invulnerability phases."}, roles = {{id = "everyone", label = "Everyone", tips = {"The leader chooses [begin] at the Echo Guide. Say [status] for the current combat objective.", "Pull when ready. Named abilities begin when the boss is engaged."}}, {id = "tank", label = "Tank", tips = {"Kill the two 3,000-HP Ceremony Warders to release the named.", "Pick up the two ushers summoned at half health."}}, {id = "damage", label = "Damage dealers", tips = {"Keep attacking Orsella. Her vow cast does not make her invulnerable.", "Kill or control the 2,500-HP ushers."}}, {id = "support", label = "Healers and control", tips = {"Interrupt Unbroken Vow when possible. The six-second cast recurs every 36 seconds.", "A completed vow deals a 450 magic damage party pulse; it does not reset the fight."}}}, phases = {{label = "Ceremony Warders", trigger = "Before Orsella appears", description = "Kill both chapel warders. Each death is saved, so a later wipe does not repeat this preparation."}, {label = "Orsella", trigger = "Both warders are dead", description = "Tank the celebrant, handle the two ushers at 50% and interrupt her vow cast or heal through its pulse. Her death ends the wedding."}}, abilities = {{name = "Unbroken Vow", summary = "Interrupt the six-second vow.", description = {"Every 36 seconds, Orsella begins a six-second interruptible cast. Completion deals 450 magic damage to the party.", "A missed interrupt is a healing challenge, not a failed delivery or a ceremony reset."}, tags = {"Interruptible", "Party damage"}, roles = {"everyone"}}, {name = "Wedding Ushers", summary = "Handle one pair of adds.", description = {"Two 2,500-HP ushers join once at 50% health. They can be killed or controlled; the celebrant remains vulnerable."}, tags = {"Adds", "Crowd control"}, roles = {"everyone"}}}, sections = {{title = "Expedition access and route", paragraphs = {"The Seven Silences admits groups of three to six characters of level 55 or higher; six level-60 characters are recommended. Speak to Keeper Avel Rimeglass in Iceclad. Entry requires no raid trophy.", "The eight-hour expedition and replay begin at acceptance. The lower floors start below the difficulty of the Mistmoore group expedition, then increase toward comparable pressure on the upper floors.", "Ordinary tower keys, keyring entries and the summit shortcut do not unlock this version. Each floor victory unlocks the next expedition mirror and a cleared return checkpoint. The two wings of floor six form one encounter."}, bullets = {}}, {title = "Warnings and recovery", paragraphs = {"Read the named cast warnings and say [status] for the current objective. The leader chooses [begin] at the Echo Guide, then the party pulls when ready. Boss abilities begin on engagement; a completed disengage resets the attempt.", "Defeated prerequisite warders and optional support mobs are saved before their deaths are accepted. A wipe or reload retains these kills, previously won floors, paid admission and replay deadlines. Cleared bosses cannot be repeated for another reward during this expedition.", "The group floors require no carried tools, book choices, bells, rings or valves. Ordinary tower keys and movement shortcuts still cannot bypass the event mirrors. Every group boss retains one of its four equipment rewards and its independent splinter roll.", "Root, mez and stun can help with ordinary adds. Interrupting a named is optional; when a cast is missed, the party can move or heal as described. No random loot item is required to perform a mechanic."}, bullets = {}}, {title = "Tower inhabitants", paragraphs = {"The full tower has 200 independent ambient positions across its floors and wings. Each area has between 12 and 44 inhabitants, including two native patrols, with more inhabitants in the larger rooms and corridors. Most see normal invisibility, many are genuinely undead, and nearby inhabitants can assist one another.", "Ordinary ambient kills do not complete the main named objectives, open mirrors, remove main named protections or award boss equipment or progression items.", "Ambient mobs can be rooted, mezzed, stunned or snared. Their saved 30-minute respawns wait near living players and during an engaged named fight on that floor. Native undead-targeted spells and invisibility-versus-undead detection use their actual body types.", "Ambient health ranges from 2,160 on the lowest floor to 6,240 at the summit. Native melee endpoints range from 36–96 to 66–186 before combat mitigation, about 20 percent above their previous tuning. The original spawn identities remain stable, so saved clears and respawn deadlines still apply after a reload."}, bullets = {}}}},
  ["tofs-vhalsera-and-the-borrowed-heart"] = {overview = {"VhalSera borrows his protection from two captive souls. Breaking a reliquary frees its prisoner, but the binding ends only when that prisoner reaches the Heart.", "The freed spirits are friendly. Protect their journey and control the gaolers; killing a friendly prisoner is neither required nor possible."}, roles = {{id = "everyone", label = "Everyone", tips = {"Stay with the encounter in the upper wing after the conduit preparation.", "Leave the Heart destination and the guidance route clear.", "Move away from Time Owed drops after their warning."}}, {id = "guide", label = "Prisoner guides", tips = {"Activate the freed prisoner's guidance interaction and remain nearby along the route.", "If a guide is lost, the prisoner waits at an approved waypoint for a replacement.", "The journey takes at least 15 seconds; do not abandon the spirit after the first interaction."}}, {id = "control", label = "Gaoler control", tips = {"Each rescue summons two 10,000-health gaolers; at most four can be alive.", "Interrupt recapture with damage, stun or distance, or root, mez, tank or kill the gaoler before it reaches the prisoner."}}, {id = "damage", label = "Damage dealers", tips = {"Attack the currently exposed 25,000-health reliquary.", "Both prisoners must arrive before VhalSera can pass 25% health.", "After 30%, interrupt the furnace cast."}}, {id = "healer", label = "Healers", tips = {"Keep the guide supported without standing on the prisoner route.", "The cold patches tick every six seconds and have no immediate impact hit."}}}, phases = {{label = "The lower conduits", trigger = "Floor 6A preparation", description = "Defeat the three conduit guardians to open 6B. The preparation remains complete after a boss wipe."}, {label = "Two borrowed lives", trigger = "Until both prisoners reach the Heart", description = "A 30-second cycle exposes one reliquary at a time. VhalSera takes only 30% damage while a binding remains."}, {label = "Time owed", trigger = "Both bindings removed", description = "VhalSera takes full damage. Continue handling the timed cold hazards."}, {label = "The furnace calls its debt", trigger = "30% health", description = "An interruptible 1,000-damage furnace cast joins the encounter every 40 seconds."}}, abilities = {{name = "The Borrowed Bindings", summary = "Break the exposed reliquary, then finish its rescue.", description = {"Each exposed reliquary has 25,000 health. Breaking it releases one friendly prisoner and two hostile gaolers.", "Reaching the Heart removes a binding permanently for the attempt. Recapture instead restores that reliquary after 20 seconds, allowing another rescue.", "VhalSera cannot fall below 25% while any binding remains."}, tags = {"Required objective", "Shield gate"}, roles = {"everyone"}}, {name = "The Gaolers' Claim", summary = "Interrupt the three-second recapture channel.", description = {"A gaoler within eight paces of a prisoner begins a visible three-second channel. Damage, stun or movement outside eight paces interrupts it.", "A guide who dies, disconnects or leaves releases the assignment. The spirit waits for another guide and remains vulnerable to recapture."}, tags = {"Protect an ally", "Channel", "Crowd control"}, roles = {"everyone"}}, {name = "Time Owed", summary = "After the eight-second warning, leave the cold patch behind.", description = {"Every 30 seconds, up to three distinct living non-tanks are warned. At warning expiry, an 18-second, ten-pace cold patch appears at the approved hazard point nearest each target. Read its visible marker and leave that point.", "A patch deals 200 cold damage on each six-second tick, without an immediate impact hit. Overlapping patches do not multiply a single tick.", "Hazards use fixed approved points outside the protected Heart destination. They do not follow a player after appearing."}, tags = {"Eight-second warning", "Ground danger"}, roles = {"everyone"}}, {name = "Furnace Debt", summary = "Interrupt the cast before its 1,000-damage hit.", description = {"Below 30%, this interruptible cast occurs every 40 seconds. Its impact is separated from a new Time Owed hazard tick by at least six seconds."}, tags = {"Interrupt", "Raid healing"}, roles = {"everyone"}}}, sections = {{title = "Expedition access and route", paragraphs = {"The Unwritten Hour admits 12 to 36 characters of level 55 or higher and is tuned for 24 to 36 level-60 raiders. Speak to Keeper Avel Rimeglass in Iceclad to arrange the expedition.", "The expedition lasts eight hours. A 72-hour replay begins when the first raid boss is defeated. That first victory seals the roster; arrange replacements beforehand. Disconnected members of the sealed roster may return before the expedition expires.", "The tower uses expedition mirrors and saved checkpoints. Ordinary tower keys, keyring entries and the summit shortcut do not unlock this version. Complete each floor objective before using the next mirror."}, bullets = {}}, {title = "Warnings and recovery", paragraphs = {"Read Event Messages and use the named encounter actors. Color and visual effects supplement the instructions; no required answer depends on recognizing a color alone. Keep the fight and its support inside the current encounter area.", "Evacuation returns eligible party members to the entrance of this same expedition. Gate and spells that transport you out of the tower remain available; reenter through the keeper while your expedition and membership remain valid. Binding, shadow steps, summons and transport within the tower cannot bypass its mirrors.", "A wipe restores the active boss and its attempt-only objectives. Previously completed encounters and route objectives remain completed. Cleared bosses cannot be repeated for another reward during the same expedition.", "An unsuccessful attempt does not consume another raid offering. A reset recreates temporary charges and actors for the next attempt. Return only to a checkpoint the expedition has already unlocked."}, bullets = {}}, {title = "Tower inhabitants", paragraphs = {"The full tower has 200 independent ambient positions across its floors and wings. Each area has between 12 and 44 inhabitants, including two native patrols, with more inhabitants in the larger rooms and corridors. Most see normal invisibility, many are genuinely undead, and nearby inhabitants can assist one another.", "Ordinary ambient kills do not complete the main named objectives, open mirrors, remove main named protections or award boss equipment or progression items.", "Ambient mobs can be rooted, mezzed, stunned or snared. Their saved 30-minute respawns wait near living players and during an engaged named fight on that floor. Native undead-targeted spells and invisibility-versus-undead detection use their actual body types.", "Ambient health ranges from 2,160 on the lowest floor to 6,240 at the summit. Native melee endpoints range from 36–96 to 66–186 before combat mitigation, about 20 percent above their previous tuning. The original spawn identities remain stable, so saved clears and respawn deadlines still apply after a reload."}, bullets = {}}}},
  ["solrotower-arlyxir"] = {overview = {"Keep Arlyxir inside his room and finish before his rebirth heal."}, roles = {{id = "everyone", label = "Everyone", tips = {"Maintain damage and keep the tank safely inside the room."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The boss checks his room boundary every six seconds. Crossing south of it heals him fully, returns him to bind and clears hate.", "After 12.5 minutes of continuous combat, Arlyxir heals and casts Searing Flames.", "Victory creates a planar projection for progression."}}}},
  ["solrotower-galremos"] = {overview = {"Galremos breaks into smaller pieces as increasingly large magmite groups appear."}, roles = {{id = "everyone", label = "Everyone", tips = {"Keep add control ready for the large final two waves."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Magmites spawn at 90%, 60%, 35%, 20% and 5% health, in groups of one, two, one, four and six respectively.", "Each threshold also reduces Galremos's size.", "Five minutes out of combat removes magmites and resets the health sequence."}}}},
  ["solrotower-jiva"] = {overview = {"Jiva calls a repeating sequence of eight efreeti helpers."}, roles = {{id = "everyone", label = "Everyone", tips = {"Assign immediate pickup of each arriving efreeti."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"An efreeti arrives every 30 seconds during combat and attacks a random hate-list target.", "The eight-helper sequence loops while the fight continues.", "Ten minutes out of combat resets the counter and removes the helpers. Victory creates a planar projection."}}}},
  ["solrotower-protector-of-dresolik"] = {overview = {"Fight the Protector of Dresolik within his guarded chamber."}, roles = {{id = "everyone", label = "Everyone", tips = {"Keep the boss inside the chamber to avoid a complete reset."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The protector checks his east-west room boundary every six seconds.", "Crossing the boundary fully heals him, returns him to bind and clears hate.", "He has a 30-minute out-of-combat despawn timer; victory produces a planar projection and warders."}}}},
  ["solrotower-rizlona"] = {overview = {"Defeating Rizlona's first form reveals her dragon form."}, roles = {{id = "everyone", label = "Everyone", tips = {"Keep the raid ready for an immediate second target when the first form falls."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The first form's death spawns the second form immediately at the same position.", "Both forms enforce a room boundary; pulling the first form south of the room heals and resets it.", "The dragon form has an out-of-combat despawn timer and provides the final progression projection."}}}},
  ["solrotower-solusek-ro"] = {overview = {"Defeat Solusek Ro in his elevated chamber and claim the progression projection."}, roles = {{id = "everyone", label = "Everyone", tips = {"Keep the fight on the intended chamber floor."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Every six seconds of combat, Solusek checks whether he has been pulled below the chamber's allowed height.", "If pulled below the height boundary, he returns to bind and clears his hate list.", "Victory creates a planar projection and signals the tower's progression controller."}}}},
  ["solrotower-xuzl"] = {overview = {"Xuzl repeatedly summons animated swords to attack the raid."}, roles = {{id = "everyone", label = "Everyone", tips = {"Prepare repeated add pickup and avoid pulling Xuzl beyond his room."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Eight swords arrive after 45 seconds; further groups arrive every 30 seconds.", "Each sword begins attacking a random member of Xuzl's hate list.", "Crossing his southern room boundary returns him to bind and clears hate.", "Swords are removed on victory or after 30 seconds out of combat."}}}},
  ["txevu-ancient-cragbeast-matriarch"] = {overview = {"Weaken the Ancient Cragbeast Matriarch by removing the bearers that sustain her abilities."}, roles = {{id = "everyone", label = "Everyone", tips = {"Clear the bearers that support the most dangerous abilities before committing to the matriarch."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Living bearers grant separate benefits including rampage, flurry, regeneration, stronger attacks, resistance and mitigation.", "One bearer enables three hatchlings every thirty-five seconds; another enables a randomly timed conflagration attack.", "Killing each bearer removes its matching benefit from the matriarch.", "The hatchlings have their own area boundary, so keep add control inside the encounter space."}}}},
  ["txevu-high-priest-nkosi-bakari"] = {overview = {"Gather the five ritualist shades, then overcome their possession and healing link to the High Priest."}, roles = {{id = "everyone", label = "Everyone", tips = {"Control the shades and plan around their charm rather than allowing repeated full boss heals."}}}, phases = {{label = "Ritual", trigger = "Five invokers and their chanters", description = "Release the shades and allow all five to reach the ritual."}, {label = "Priest and shades", trigger = "Fifth shade arrives", description = "Control possession and remove the shades that can replenish the priest at half health."}}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Defeating the five invokers releases shades that travel to the central ritual.", "The fifth arrival summons Nkosi Bakari and makes the shades attackable.", "Engaged shades attempt Spiritual Possession after fifteen seconds; a shade returns when its possession ends.", "At half health, the High Priest can absorb a surviving shade and return to full health, repeating while shades remain.", "The priest and shades reset if pulled out of their permitted area."}}}},
  ["txevu-ikaav-nysf-lleiv"] = {overview = {"Defeat newly vulnerable stonemasters to slow and stop Ikaav Nysf Lleiv's rockchanters."}, roles = {{id = "everyone", label = "Everyone", tips = {"Switch to each stonemaster as its shield falls and keep spawned rockchanters controlled."}}}, phases = {{label = "Hateq", trigger = "75% health", description = "Remove the first stonemaster while managing charm."}, {label = "Lorasa", trigger = "50% health", description = "Remove the second stonemaster as Malicious Intent joins the fight."}, {label = "Veset", trigger = "25% health", description = "Remove the last stonemaster to end rockchanter spawning through the flame cycle."}}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Rockchanters initially arrive every thirty seconds while three stonemasters remain; fewer survivors extend the interval to sixty and ninety seconds.", "At 75%, Hateq becomes vulnerable and the boss gains charm.", "At 50%, Lorasa becomes vulnerable and Malicious Intent begins.", "At 25%, Veset becomes vulnerable and Curse of Flames begins. Killing the final stonemaster stops new rockchanters.", "Losing combat heals the boss and schedules a twenty-minute event reset."}}}},
  ["txevu-mastruq-champion-ixt-hsek-syat"] = {overview = {"Honor the arena's opening duel, then fight the champion and Ixt Hsek Syat inside the pit."}, roles = {{id = "everyone", label = "Everyone", tips = {"Choose one duelist and avoid pets or outside healing that could join the Runt's hate list.", "After the duel, assign both bosses and the remaining arena adds."}}}, phases = {{label = "The duel", trigger = "Runt appears", description = "A single combatant must defeat the Runt without assistance."}, {label = "Arena finale", trigger = "Runt defeated", description = "Control both named opponents and the fighters they call."}}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Entering the arena starts the dialogue and summons the Runt for a solo challenge.", "More than one entry on the Runt's hate list counts as cheating and activates the spectators and champion.", "Killing the Runt summons Ixt and makes the champion vulnerable.", "At 90%, Ixt calls the remaining arena fighters; at 20%, he calls the champion if free. The champion also calls Ixt at 20%.", "The arena opponents return and reset hate when pulled outside the pit."}}}},
  ["txevu-ukun-bloodfeaster"] = {overview = {"Fight the Bloodfeaster and its maulers while corpses feed a recurring stonemite swarm."}, roles = {{id = "everyone", label = "Everyone", tips = {"Control the maulers and reduce the corpse-driven add pressure before stonemites overwhelm the raid."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Starting the event removes protection from the Bloodfeaster, maulers and decaying corpses.", "Every thirty seconds, surviving corpses are signaled to create pairs of stonemites while the active add count is below thirty-six.", "The boss and adds return and clear hate outside their room boundaries.", "The forty-five-minute event reset timer pauses while the Bloodfeaster is engaged."}}}},
  ["txevu-zun-muram-tkarish-zyk"] = {overview = {"Maintain tank coverage through Zun`Muram's banishments while suppressing ritualist reinforcements."}, roles = {{id = "everyone", label = "Everyone", tips = {"Keep a backup tank ready for banishment and free jailed players promptly.", "Assign ritualist kills to stop their recurring waves."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"A check every twenty-five seconds can banish the top-threat target to a northern or southern jail.", "Leaving a player in jail for twenty seconds brings six apparitions into that room.", "Four ritualists begin staggered reinforcement waves after thirty, sixty, ninety and 120 seconds, then repeat every two minutes while their ritualist survives.", "The boss, inquisitors and ritualists share aggression; the main chamber boundary resets targets pulled outside it."}}}},
  ["uqua-tqiv-araxt-the-enraged-and-tqiv-qukret-the-furious"] = {overview = {"Coordinate the two twins' deaths before the survivor absorbs its partner's power."}, roles = {{id = "everyone", label = "Everyone", tips = {"Balance damage and finish the second twin within thirty seconds of the first."}}}, phases = {{label = "Constructs", trigger = "Before activation", description = "Clear both sides and prepare coordinated boss damage."}, {label = "Twin finish", trigger = "First twin dies", description = "Defeat the survivor before its thirty-second absorption timer expires."}}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Clear the constructs on each side to remove the matching twin's protection.", "Once a twin is active, its thirty-minute failure timer can restore protection and respawn four constructs.", "A twin's death starts a thirty-second absorption window on the survivor. If that expires, the survivor heals fully and gains stronger defenses, melee and spells.", "Player or pet deaths to either twin can create hostile spirits.", "Each twin drops a progression orb as a ground object."}}}},
}
